    </style>
</head>
<body>

<div id="claim-form">
    <h2>Disability Claim Submission</h2>
    <div>
        <label for="policy-number">Policy Number:</label>
        <input type="text" id="policy-number" required>
    </div>
    <div>
        <label for="member-id">Member ID:</label>
        <input type="text" id="member-id" required>
        <button type="button" onclick="lookupMember()">Look up member</button>
        <div id="member-details"></div>
    </div>
    <hr>
    <h3>Claim Details</h3>
    <div>
        <label for="last-day-worked">Last Day Worked:</label>
        <input type="date" id="last-day-worked" required>
    </div>
    <div>
        <label for="first-day-absent">First Day Absent:</label>
        <input type="date" id="first-day-absent" required>
    </div>
    <div>
        <label for="nature-of-absence">Nature of Absence:</label>
        <select id="nature-of-absence" required>
            <option value="">Select...</option>
            <option value="sick">Sick</option>
            <option value="injury">Injury</option>
            <option value="other">Other</option>
        </select>
    </div>
    <div>
        <label for="details">Details:</label>
        <textarea id="details"></textarea>
    </div>
    <div>
        <label for="documents">Upload Documents:</label>
        <input type="file" id="documents" multiple onchange="updateFileList()">
        <ul id="file-list"></ul>
    </div>
    <button type="button" onclick="submitForm()">Submit Claim</button>
</div>

<div id="confirmation">
    <h2>Claim Submission</h2>
    <p>Reference Number: <span id="reference-number"></span></p>
    <p>Status: Received</p>
</div>

<footer>
    MapleSure Insurance &mdash; fictional demo application
</footer>

<script>
    const mockData = {
        "12345": { name: "John Doe", memberSince: "2020-01-01" },
        "23456": { name: "Jane Smith", memberSince: "2019-05-15" }
    };

    function lookupMember() {
        const memberId = document.getElementById("member-id").value;
        const detailsDiv = document.getElementById("member-details");
        if (mockData[memberId]) {
            const member = mockData[memberId];
            detailsDiv.innerHTML = `<p>Name: ${member.name}</p><p>Member Since: ${member.memberSince}</p>`;
        } else {
            detailsDiv.innerHTML = `<p>Member not found.</p>`;
        }
    }

    function updateFileList() {
        const input = document.getElementById("documents");
        const list = document.getElementById("file-list");
        list.innerHTML = "";
        for (let i = 0; i < input.files.length; i++) {
            const li = document.createElement("li");
            li.textContent = input.files[i].name;
            list.appendChild(li);
        }
    }

    function generateReferenceNumber() {
        const year = new Date().getFullYear();
        const randomSegment = Math.floor(1000 + Math.random() * 9000);
        return `MS-${year}-08-${randomSegment}`;
    }

    function submitForm() {
        document.getElementById("claim-form").style.display = "none";
        const refNumber = generateReferenceNumber();
        document.getElementById("reference-number").textContent = refNumber;
        document.getElementById("confirmation").style.display = "block";
    }
</script>

</body>
</html>


